export function initCrew(s){s.roster=Array.from({length:12},(_,i)=>({id:i+1,slot:i,kind:'SPP',present:true,engine:null}));s.roster[11].role='nurse';s.freeStaff=11;s.roster.push({id:13,slot:18,kind:'SPP',role:'captain',present:true,engine:null});}
export function duty(minute){const h=minute/60%24;return h<6||h>=22?'dormitory':h<8?'breakfast':h<10?'equipment':h<12?'sport':h<14?'meal':h<18?'training':h<19?'sport':h<21?'meal':'rest';}
export const dutyLabels={dormitory:'Repos au dortoir',breakfast:'Petit-déjeuner',equipment:'Vérification et rangement',sport:'Sport',meal:'Repas',training:'Manœuvre et entretien',rest:'Temps calme'};
export function crewPosition(p,minute){const i=p.slot??((p.id-1)%50),task=duty(minute);if(i>=19){const n=i-19;if(task==='dormitory'||task==='rest')return[-89+(n%10)*4,14+Math.floor(n/10)*4];if(task==='meal'||task==='breakfast')return[-75+(n%8)*2,33+Math.floor(n/8)*2];return[-90+(n%12)*3.4,36+Math.floor(n/12)*4];}if(task==='dormitory'||task==='rest')return[-87+(i%6)*6,19+Math.floor(i/6)*5];if(task==='meal'||task==='breakfast')return[-73+(i%6)*1.4,40+Math.floor(i/6)*3];if(task==='sport')return[-89+(i%4)*2.3,39+Math.floor(i/4)*2];return[-57+(i%4)*2,38+Math.floor(i/4)*2];}
export function syncCrew(s){s.freeStaff=s.roster.filter(p=>p.present&&!p.engine&&!['captain','nurse'].includes(p.role)).length;s.spv=s.roster.some(p=>p.present&&p.kind==='SPV');}
export function assignCrew(s,e){const candidates=s.roster.filter(p=>p.present&&!p.engine&&(e.kind==='VLCG'?p.role==='captain':e.kind==='VLI'?p.role==='nurse':!['captain','nurse'].includes(p.role)));if(candidates.length<e.size)return false;e.crewIds=candidates.slice(0,e.size).map(p=>{p.engine=e.id;return p.id;});e.crew=e.crewIds.length;syncCrew(s);return true;}
export function releaseCrew(s,e){s.roster.filter(p=>p.engine===e.id).forEach(p=>p.engine=null);e.crewIds=[];e.crew=0;syncCrew(s);}
export function recallCrew(s,count){let next=Math.max(0,...s.roster.map(p=>p.id))+1;for(let i=0;i<count;i++){const slot=Array.from({length:18},(_,n)=>n).find(n=>!s.roster.some(p=>p.present&&p.slot===n));if(slot===undefined)break;s.roster.push({id:next++,slot,kind:'SPV',present:true,engine:null});}syncCrew(s);}
export function dismissCrew(s){let n=0;for(const p of s.roster)if(p.present&&p.kind==='SPV'&&!p.engine){p.present=false;n++;}syncCrew(s);return n;}
export function prepareCrew(s,e,rnd=Math.random){e.boarding=(e.crewIds||[]).map(id=>{const p=s.roster.find(p=>p.id===id),from=crewPosition(p,s.minute),locker=[-72,51];const wake=duty(s.minute)==='dormitory'?1+rnd()*2:0,equip=1.2+rnd()*1.4,walk=(Math.hypot(from[0]-locker[0],from[1]-locker[1])+Math.hypot(e.home[0]-locker[0],e.home[1]-locker[1]))/14;return{id,from,locker,delay:wake+equip,duration:wake+equip+walk};});return Math.max(0,...e.boarding.map(p=>p.duration));}
